const int MOTOR = 9;
const unsigned long HALF_PERIOD = 1000;
unsigned long last = 0;
bool on = false;

void setup() {
  pinMode(MOTOR, OUTPUT);
}

void loop() {
  if (millis() - last >= HALF_PERIOD) {
    last += HALF_PERIOD;
    on = !on;
    digitalWrite(MOTOR, on ? HIGH : LOW);
  }
}

