const int MOTOR = 9;

void setup() {
  pinMode(MOTOR, OUTPUT);
}

void loop() {
  digitalWrite(MOTOR, HIGH);
  delay(1000);             // blocks the whole sketch for a second
  digitalWrite(MOTOR, LOW);
  delay(1000);
}

